"""``gk_load_quantity`` -- load a pre-named gyrokinetic quantity by name."""

from __future__ import annotations

import re

import click

import postgkyl as pg

from .._options import label_option, tag_option


@click.command("gk_load_quantity")
@click.option("--quantity", "-q", default=None, help="Registered quantity name.")
@click.option("--qlist", is_flag=True, default=False,
    help="List the available quantities and exit.")
@click.option("--name", "-n", default=None, help="Simulation name prefix.")
@click.option("--species", "-s", default=None,
    help="Species name, or a comma-separated list (species-independent quantities: omit).")
@click.option("--frame", "-f", default=None,
    help="Frame number, comma-separated list, or 'start:stop[:step]' range; default: all.")
@click.option("--path", "-p", default="./", help="Directory containing the simulation files.")
@click.option("--extra", "-e", default=None,
    help="Extra comma-separated key=value pairs of extra commands, e.g. dir=1,mass=0.1. "
         "A key may be given one value per species as a comma-separated array, e.g. "
         "mass=me,mi1,mi2 alongside --species elc,ion1,ion2. Purpose depends on -q.")
@tag_option(default="default")
@label_option()
@click.pass_context
def command(ctx, quantity, qlist, name, species, frame, path, extra, tag, label) -> None:
  """Gyrokinetics: load and compute a pre-named quantity by name.

  Use --qlist to print the registered quantity names.
  """
  if qlist:
    click.echo(f"Available quantities: {', '.join(pg.available_gk_quantities())}.")
    return
  # end
  if not quantity or not name:
    raise click.UsageError("gk_load_quantity: --quantity and --name are required (unless --qlist)")
  # end
  datasets = pg.load_gk_quantity(quantity, species, name, frame, path=path,
      tag=tag, label=label, **_parse_extra(extra))
  ctx.obj.datasets.extend(datasets)
# end


def _parse_extra(extra: str | None) -> dict:
  """Parse ``--extra``'s ``key=value,...`` syntax, coercing numeric values.

  Pairs may be separated by commas or whitespace (``mass=1,2 dir=0`` and
  ``mass=1,2,dir=0`` both work -- needed since a value itself may be a
  comma-separated array). A value with more than one comma-separated entry
  is kept as a list, one entry per species in ``--species`` order; a
  single value stays a scalar and applies to every species.
  """
  parsed = {}
  if not extra:
    return parsed
  # end
  for pair in re.split(r"[,\s]+(?=[^\s,=]+=)", extra.strip()):
    key, _, val = pair.partition("=")
    vals = []
    for v in val.split(","):
      v = v.strip()
      if not v:
        continue
      # end
      try:
        v = int(v)
      except ValueError:
        try:
          v = float(v)
        except ValueError:
          pass
        # end
      # end
      vals.append(v)
    # end
    parsed[key.strip()] = vals[0] if len(vals) == 1 else vals
  # end
  return parsed
# end

"""``gk_distf`` -- build a gyrokinetic distribution function from saved Jf data."""

from __future__ import annotations

import click

import postgkyl as pg

from .._options import label_option, tag_option


@click.command("gk_distf")
@click.option("--name", "-n", required=True, help="Simulation name prefix.")
@click.option("--species", "-s", required=True, help="Species name.")
@click.option("--frame", "-f", required=True,
    help="Frame number, comma-separated list, or 'start:stop[:step]' range.")
@click.option("--suffix", default="",
    help="Use '<name>-<species>_<suffix>_<frame>.gkyl' as the input.")
@click.option("--num-interp", "-i", "num_interp", type=int, default=None,
    help="Interpolation points per cell (default: poly_order + 1).")
@click.option("--c2p-vel", "-v", "c2p_vel", is_flag=True, default=False,
    help="Convert velocity-space coordinates via the mapc2p_vel mapping.")
@click.option("--mc2nu", "-m", is_flag=True, default=False,
    help="Convert to field-aligned coordinates via the mc2nu mapping.")
@click.option("--mapc2p", "-p", is_flag=True, default=False,
    help="Convert position-space coordinates via the mapc2p mapping.")
@click.option("--block", "-b", type=int, default=None,
    help="Use block-specific files with a '_b<idx>' prefix.")
@click.option("--jf-file", default=None, help="Jf filename override.")
@click.option("--jacobvel-file", default=None, help="jacobvel filename override.")
@click.option("--jacobtot-inv-file", default=None, help="jacobtot_inv filename override.")
@click.option("--mc2nu-file", default=None, help="mc2nu filename override.")
@click.option("--mapc2p-file", default=None, help="mapc2p filename override.")
@click.option("--mapc2p-vel-file", default=None, help="mapc2p_vel filename override.")
@tag_option(default="f")
@label_option()
@click.pass_context
def command(ctx, name, species, frame, suffix, num_interp, c2p_vel, mc2nu, mapc2p,
    block, jf_file, jacobvel_file, jacobtot_inv_file, mc2nu_file, mapc2p_file,
    mapc2p_vel_file, tag, label) -> None:
  """Gyrokinetics: build f from a saved Jf-times-Jacobian(s) file."""
  frames = pg.diagnostics.gyrokinetics.resolve_frames(frame, name=name,
      species=species, suffix=suffix, block_idx=block)
  for f in frames:
    out = pg.load_gk_distf(name, species, f, tag=tag, suffix=suffix,
        use_c2p_vel=c2p_vel, use_mc2nu=mc2nu, use_mapc2p=mapc2p,
        block_idx=block, num_interp=num_interp, jf_file=jf_file,
        jacobvel_file=jacobvel_file, jacobtot_inv_file=jacobtot_inv_file,
        mc2nu_file=mc2nu_file, mapc2p_file=mapc2p_file,
        mapc2p_vel_file=mapc2p_vel_file)
    if label:
      out.label = label
    # end
    ctx.obj.datasets.append(out)
# end
  # end

"""``status`` -- activate/deactivate datasets in the working set, by index."""

from __future__ import annotations

import click

from .._apply import is_active, parse_indices, set_active


@click.command("status")
@click.option("--activate", "-a", "activate_spec", default=None,
    help="Index spec to activate: '1', '0,2,5', '1:6:2', or ':' for all.")
@click.option("--deactivate", "-d", "deactivate_spec", default=None,
    help="Index spec to deactivate; same forms as --activate.")
@click.pass_context
def command(ctx, activate_spec, deactivate_spec) -> None:
  """Activate/deactivate datasets in the working set (by index).

  Deactivated datasets are skipped by transform commands (fft, magsq, ...)
  and by the terminal commands (info, plot, save). With neither option,
  prints the current active/inactive status of every dataset.
  """
  datasets = ctx.obj.datasets
  if activate_spec is not None:
    for i in parse_indices(activate_spec, len(datasets)):
      set_active(datasets[i], True)
    # end
  # end
  if deactivate_spec is not None:
    for i in parse_indices(deactivate_spec, len(datasets)):
      set_active(datasets[i], False)
    # end
  # end
  if activate_spec is None and deactivate_spec is None:
    for i, d in enumerate(datasets):
      state = "active" if is_active(d) else "inactive"
      click.echo(f"[{i}] {state}  tag={d.tag!r}")
# end
    # end
  # end

"""``listoutputs`` -- list Gkeyll filename stems found in a directory."""

from __future__ import annotations

import click

import postgkyl as pg


@click.command("listoutputs")
@click.option("--extensions", "-e", default="gkyl",
    help="Comma-separated output file extension(s).")
@click.option("--path", "-p", default=".", help="Directory to search for outputs.")
@click.pass_context
def command(ctx, extensions, path) -> None:
  """List the Gkeyll filename stems (per extension) found in a directory."""
  stems_by_ext = pg.diagnostics.discovery.find_output_stems(extensions, path)
  for ext, stems in stems_by_ext.items():
    if stems:
      click.echo(f"{ext}:")
    # end
    for stem in stems:
      click.echo(f"- {stem}")
# end
    # end
  # end

"""``style`` -- probe and control the Matplotlib plotting style."""

from __future__ import annotations

import click


@click.command("style")
@click.option("--file", "-f", default=None,
    help="Matplotlib style name (e.g. 'postgkyl', 'dark_background') or .mplstyle file path.")
@click.option("--set", "-s", "set_params", multiple=True,
    help="Set an individual rcParam as 'key:value' (repeatable).")
@click.option("--print", "-p", "print_flag", is_flag=True, default=False,
    help="Print the current rcParams.")
@click.pass_context
def command(ctx, file, set_params, print_flag) -> None:
  """Apply a Matplotlib style and/or set/print individual rcParams."""
  import matplotlib as mpl

  import postgkyl as pg

  if file:
    pg.render.style.apply_style(file)
  # end
  for param in set_params:
    key, _, value = param.partition(":")
    mpl.rcParams[key.strip()] = value.strip()
  # end
  if print_flag:
    for key, value in mpl.rcParams.items():
      click.echo(f"{key} : {value}")
# end
    # end
  # end

